from pathlib import Path
entry='''\n\n## 2026-10-18 악보 부분 재조판·입당 mock·안내 중첩 v17\n- 사용자가 완료된 악보부터 부분 반영하도록 요청. 기존 완성 PDF가 없음을 확인하고 원본 21번 아멘을 직접 전사·대조하여 먼저 제작. 음표 11개, 점음표/이음줄/한 개 내림표, 아멘 3회 가사. 본당 최종 교정 전 상태를 파일과 카드에 표시.\n- output/pdf/amen-reengraved.pdf 및 docs/교중미사악보/reengraved/amen.pdf, amen.svg, amen.musicxml, amen-manifest.json 생성. PDF는 벡터이며 원본 사진을 삽입하지 않음. 뷰어에는 같은 음표·가사의 SVG 미리보기와 PDF 열기 링크를 연결. 새 조판 우선 레지스트리를 추가하되 교중 회차 범위 유지. 나머지 곡은 기존 임시 사진 보존. 전체 교체 완료 아님.\n- PDF skill 렌더 검사: 한글 가사가 초기 렌더에서 빠진 문제를 SVG 텍스트 폰트/중첩 구조 수정 후 재생성. pdftoppm proof.png를 실제 열어 음표·가사·여백·각주 잘림 없음 확인.\n- 사용자가 지적한 입당 성가 안내 2개 제거. 입당 성가는 한 페이지 가용 높이의 악보 카드, “악보 표시 영역 · mock”과 배치용 가상 오선/음표만 표시. docs/mock/entrance-score.svg는 실제 편성 성가가 아님.\n- 합송 중간 안내는 별도 들여쓰기 보정 대신 reader__speech-body 내부로 이동. 기호와 본문 2열 유지, 이어지는 본문·안내가 같은 본문 컨테이너에 담김.\n- 검사: node --check work/review-ia-v17-check.js, node work/test-reader-v17.cjs, 번들 Python work/check_amen.py 통과. 기존 흐름/튜토리얼/날짜/합송 회귀, 내부 안내 중첩, 입당 full-height mock, 아멘 vector/PDF 연결·다른 사진 fallback·회차 범위, PDF 1쪽/이미지 없음/한글 가사/전사 음표 구조/원본 8개 해시 보존 확인. 실제 브라우저 높이·PDF 열기 동작은 모의 검사 외 미실행.\n- review/02-ia-v17.html 제안. v16 보존. 2단계 검토 대기.\n'''
for name in ['docs/progress.md','design.md','ENGINEERING.md','README.md']:
 p=Path(name);Path('scratch/'+p.name+'.before-v17').write_bytes(p.read_bytes())
 text=entry if name!='README.md' else '\n\n## 최신 검토 v17\nreview/02-ia-v17.html: 아멘 재조판 부분 반영(PDF+SVG+MusicXML), 입당 성가 한 페이지 mock, 본문 컨테이너 내부 안내. 검사: node work/test-reader-v17.cjs, 번들 Python work/check_amen.py. 새 PDF는 output/pdf/amen-reengraved.pdf. 다른 곡의 전체 재조판은 미완료입니다.\n'
 p.write_text(p.read_text(encoding='utf-8')+text,encoding='utf-8',newline='\r\n')
